// Lie factor: visual ratio over data ratio (plain JS)
function lieFactor(dataA, dataB, pxA, pxB) {
  const dataRatio = (dataB - dataA) / dataA;
  const pxRatio = (pxB - pxA) / pxA;
  return pxRatio / dataRatio;
}
// Truncated 82-vs-85 bars (px 10 vs 100): data 3.6%, visual 900% → factor ~250.
// Zero-based same bars: factor ≈ 1.0 (honest by construction).

