function lieFactor(dataA, dataB, pxA, pxB) {
  const dataRatio = (dataB - dataA) / dataA;
  const pxRatio = (pxB - pxA) / pxA;
  return Math.round((pxRatio / dataRatio) * 10) / 10;
}
console.log('truncated bars: ' + lieFactor(82, 85, 10, 100));
console.log('honest bars: ' + lieFactor(82, 85, 82, 85));
